import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import Chart from 'chart.js/auto'; // import Chart.js (v4+)

const App = () => {
  // State for expense list, form values, and dark mode toggle
  const [expenses, setExpenses] = useState([]);
  const [form, setForm] = useState({ name: '', amount: '', date: '', category: 'Food' });
  const [darkMode, setDarkMode] = useState(false);

  // Refs for canvases for Chart.js
  const expenseChartRef = useRef(null);
  const dailyChartRef = useRef(null);
  const monthlyChartRef = useRef(null);
  const barChartRef = useRef(null);

  // Variables to hold Chart instances so we can destroy them before re-creating
  const chartInstancesRef = useRef({ expenseChart: null, dailyChart: null, monthlyChart: null, barChart: null });

  // API URL
  const API_URL = 'http://localhost:5000/api/expenses';

  // Fetch expenses from Node API
  const fetchExpenses = async () => {
    try {
      const res = await axios.get(API_URL);
      setExpenses(res.data);
    } catch (error) {
      console.error('Error fetching expenses:', error);
    }
  };

  // Called when component mounts to load expenses
  useEffect(() => {
    fetchExpenses();
  }, []);

  // Update charts when expenses or darkMode change
  useEffect(() => {
    updateCharts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expenses, darkMode]);

  // Handle form field changes
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // Add a new expense using API
  const addExpense = async () => {
    if (!form.name || !form.amount || !form.date) {
      alert('Please enter all fields');
      return;
    }
    try {
      await axios.post(API_URL, form);
      setForm({ name: '', amount: '', date: '', category: 'Food' });
      fetchExpenses();
    } catch (error) {
      console.error('Error adding expense:', error);
    }
  };

  // Delete an expense by its id
  const deleteExpense = async (id) => {
    try {
      await axios.delete(`${API_URL}/${id}`);
      fetchExpenses();
    } catch (error) {
      console.error('Error deleting expense:', error);
    }
  };

  // Utility to destroy existing charts if they exist
  const destroyCharts = () => {
    Object.values(chartInstancesRef.current).forEach((chartInst) => {
      if (chartInst) chartInst.destroy();
    });
    chartInstancesRef.current = { expenseChart: null, dailyChart: null, monthlyChart: null, barChart: null };
  };

  // Function to update all charts using Chart.js
  const updateCharts = () => {
    destroyCharts();

    // Prepare aggregated data
    const categories = {};
    const dailyTotals = {};
    const monthlyTotals = {};

    expenses.forEach(exp => {
      // Aggregate by category
      categories[exp.category] = (categories[exp.category] || 0) + parseFloat(exp.amount);

      // Daily totals
      dailyTotals[exp.date] = (dailyTotals[exp.date] || 0) + parseFloat(exp.amount);

      // Monthly totals (YYYY-MM)
      const month = exp.date.slice(0, 7);
      monthlyTotals[month] = (monthlyTotals[month] || 0) + parseFloat(exp.amount);
    });

    const textColor = darkMode ? "#ffffff" : "#212529";

    // Create Doughnut chart for Expense by Category
    if (expenseChartRef.current) {
      const ctx = expenseChartRef.current.getContext('2d');
      chartInstancesRef.current.expenseChart = new Chart(ctx, {
        type: 'doughnut',
        data: {
          labels: Object.keys(categories),
          datasets: [{
            data: Object.values(categories),
            backgroundColor: [
              "#00bcd4", "#8e44ad", "#f39c12", "#27ae60",
              "#e74c3c", "#3498db", "#2ecc71", "#f1c40f"
            ]
          }]
        },
        options: {
          plugins: {
            legend: {
              labels: { color: textColor }
            }
          }
        }
      });
    }

    // Create Doughnut chart for Daily Expense
    if (dailyChartRef.current) {
      const dailyCtx = dailyChartRef.current.getContext('2d');
      chartInstancesRef.current.dailyChart = new Chart(dailyCtx, {
        type: 'doughnut',
        data: {
          labels: Object.keys(dailyTotals),
          datasets: [{
            data: Object.values(dailyTotals),
            backgroundColor: [
              "#ff6b6b", "#6c5ce7", "#00cec9", "#fab1a0",
              "#e84393", "#81ecec", "#fdcb6e", "#0984e3"
            ]
          }]
        },
        options: {
          plugins: {
            legend: {
              labels: { color: textColor }
            }
          }
        }
      });
    }

    // Create Doughnut chart for Monthly Expense
    if (monthlyChartRef.current) {
      const monthlyCtx = monthlyChartRef.current.getContext('2d');
      chartInstancesRef.current.monthlyChart = new Chart(monthlyCtx, {
        type: 'doughnut',
        data: {
          labels: Object.keys(monthlyTotals),
          datasets: [{
            data: Object.values(monthlyTotals),
            backgroundColor: [
              "#1abc9c", "#c0392b", "#2c3e50", "#d35400",
              "#7f8c8d", "#34495e", "#9b59b6", "#16a085"
            ]
          }]
        },
        options: {
          plugins: {
            legend: {
              labels: { color: textColor }
            }
          }
        }
      });
    }

    // Create Bar chart for Monthly Spending
    if (barChartRef.current) {
      const barCtx = barChartRef.current.getContext('2d');
      const sortedMonthlyLabels = Object.keys(monthlyTotals).sort();
      const sortedMonthlyValues = sortedMonthlyLabels.map(label => monthlyTotals[label]);
      chartInstancesRef.current.barChart = new Chart(barCtx, {
        type: 'bar',
        data: {
          labels: sortedMonthlyLabels,
          datasets: [{
            label: 'Monthly Spending (₹)',
            data: sortedMonthlyValues,
            backgroundColor: '#4dabf7',
            borderRadius: 5
          }]
        },
        options: {
          plugins: {
            legend: {
              labels: { color: textColor }
            }
          },
          scales: {
            x: { ticks: { color: textColor } },
            y: { ticks: { color: textColor } }
          }
        }
      });
    }
  };

  // Toggle dark mode state
  const toggleDarkMode = () => {
    setDarkMode(prev => !prev);
  };

  // Calculate total spending for display
  const totalSpending = expenses.reduce((acc, exp) => acc + parseFloat(exp.amount), 0);

  return (
    <div className={darkMode ? "dark-mode" : ""}>
      <div style={{ padding: '10px', textAlign: 'right', cursor: 'pointer' }} onClick={toggleDarkMode}>
        🌓 Dark Mode
      </div>
      <div className="container">
        <h2 className="text-center mb-4">Expense Tracker</h2>
        <div className="mb-3">
          <input 
            type="text"
            id="expenseName"
            name="name"
            className="form-control"
            placeholder="Expense Name"
            value={form.name}
            onChange={handleChange}
          />
        </div>
        <div className="mb-3">
          <input 
            type="number"
            id="expenseAmount"
            name="amount"
            className="form-control"
            placeholder="Amount"
            value={form.amount}
            onChange={handleChange}
          />
        </div>
        <div className="mb-3">
          <input 
            type="date"
            id="expenseDate"
            name="date"
            className="form-control"
            value={form.date}
            onChange={handleChange}
          />
        </div>
        <div className="mb-3">
          <select
            id="expenseCategory"
            name="category"
            className="form-select"
            value={form.category}
            onChange={handleChange}
          >
            <option value="Food">Food</option>
            <option value="Transport">Transport</option>
            <option value="Shopping">Shopping</option>
            <option value="Entertainment">Entertainment</option>
            <option value="Health">Health</option>
            <option value="Education">Education</option>
            <option value="Bills">Bills</option>
            <option value="Other">Other</option>
          </select>
        </div>
        <button className="btn btn-success w-100 mb-4" onClick={addExpense}>
          Add Expense
        </button>

        <h3 className="mt-4">Expenses</h3>
        <ul className="list-group mb-4">
          {expenses.map(exp => (
            <li key={exp._id} className="list-group-item d-flex justify-content-between align-items-center">
              <div>
                <strong>{exp.name}</strong> - ₹{exp.amount} ({exp.category})<br />
                <small>{exp.date}</small>
              </div>
              <button className="delete-btn" onClick={() => deleteExpense(exp._id)}>X</button>
            </li>
          ))}
        </ul>

        <h3 className="mt-4">Total Spending: <span>₹{totalSpending.toFixed(2)}</span></h3>

        <h3 className="mt-4">Expense Overview</h3>
        <div className="row g-4">
          <div className="col-12 col-md-6">
            <div className="chart-container">
              <h4>Spending Over Time</h4>
              <canvas ref={barChartRef}></canvas>
            </div>
          </div>
          <div className="col-12 col-md-6">
            <div className="chart-container">
              <h4>By Category</h4>
              <canvas ref={expenseChartRef}></canvas>
            </div>
          </div>
          <div className="col-12 col-md-6">
            <div className="chart-container">
              <h4>Daily Expense</h4>
              <canvas ref={dailyChartRef}></canvas>
            </div>
          </div>
          <div className="col-12 col-md-6">
            <div className="chart-container">
              <h4>Monthly Expense</h4>
              <canvas ref={monthlyChartRef}></canvas>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;
